# Paste into the new machine: Brev console > clear-magenta-cougar > Open Notebook > Terminal.
# Opens SSH over a Cloudflare tunnel on port 443, because the venue Wi-Fi blocks SSH. Login still requires the Brev key.
set +H
mkdir -p ~/safe-signal ~/.ssh && chmod 700 ~/.ssh && touch ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys
grep -qF 'ssh-rsa ' ~/.ssh/authorized_keys || echo 'ssh-rsa ' >> ~/.ssh/authorized_keys
cd ~/safe-signal
[ -x ./cloudflared ] || { curl -sL -o cloudflared https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64 && chmod +x cloudflared; }
pkill -f "cloudflared tunnel --url ssh" 2>/dev/null
nohup ./cloudflared tunnel --no-autoupdate --url ssh://localhost:22 > tunnel-ssh.log 2>&1 &
sleep 15
echo; echo "===== SEND THIS BACK ====="; echo "user: $(whoami)"; echo "sshd: $(ss -ltn 2>/dev/null | grep -c ':22 ')"; nvidia-smi --query-gpu=name,memory.total --format=csv,noheader; grep -o 'https://[a-z0-9-]*\.trycloudflare\.com' tunnel-ssh.log | head -1; echo "=========================="
